/*
 * Hero Ops Console palette (prototype/capstone-build-spec.md, "Theme palette").
 * Each role is mapped onto spartan's own token. The accent (--accent) is the subtle
 * hover surface; the action colour is --primary. Semantic colours have no spartan
 * token, so they are declared here and exposed to Tailwind below.
 */
:root {
  color-scheme: light;

  --font-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans',
    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';

  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --radius: 0.625rem;

  /* action / primary */
  --primary: #d8891a;
  --primary-foreground: #ffffff;
  /* page background */
  --background: #f6f7fa;
  /* foreground (text) */
  --foreground: #1b1e2b;
  /* card / popover */
  --card: #ffffff;
  --card-foreground: #1b1e2b;
  --popover: #ffffff;
  --popover-foreground: #1b1e2b;
  /* muted surface */
  --secondary: #eef0f6;
  --secondary-foreground: #1b1e2b;
  --muted: #eef0f6;
  --muted-foreground: #5b6072;
  /* subtle hover background */
  --accent: #eef0f6;
  --accent-foreground: #1b1e2b;
  /* destructive (MIA / retire) */
  --destructive: #e5484d;
  /* border / input */
  --border: #e4e7ef;
  --input: #e4e7ef;
  /* focus ring: amber at 35% */
  --ring: rgb(216 137 26 / 35%);

  /* navigation rail: dark in both themes */
  --sidebar: #1e2233;
  --sidebar-foreground: #eceef6;
  --sidebar-primary: #d8891a;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #2a2f45;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #2a2f45;
  --sidebar-ring: rgb(216 137 26 / 35%);
  /* rail secondary text (no spartan token; the rail's muted role) */
  --sidebar-muted: #9aa0b4;

  /* semantic status colours (separate from the accent; these carry meaning) */
  --success: #2fb574;
  --warning: #e4802b;
  --info: #4f7cf0;
}

:root.dark {
  color-scheme: dark;

  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);

  --primary: #f5b843;
  --primary-foreground: #241a05;
  --background: #0e1018;
  --foreground: #eceef6;
  --card: #171a26;
  --card-foreground: #eceef6;
  --popover: #171a26;
  --popover-foreground: #eceef6;
  --secondary: #1e2231;
  --secondary-foreground: #eceef6;
  --muted: #1e2231;
  --muted-foreground: #9aa0b4;
  --accent: #1e2231;
  --accent-foreground: #eceef6;
  --destructive: #f2585d;
  --border: #272b3b;
  --input: #272b3b;
  --ring: rgb(245 184 67 / 40%);

  --sidebar: #10121c;
  --sidebar-foreground: #eceef6;
  --sidebar-primary: #f5b843;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #20263c;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #20263c;
  --sidebar-ring: rgb(245 184 67 / 40%);
  --sidebar-muted: #8b90a6;

  --success: #3ecb84;
  --warning: #f0983f;
  --info: #6f97f6;
}

/* Exposes the semantic status tokens to Tailwind utilities (bg-success, text-warning, ...). */
@theme inline {
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-info: var(--info);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

